<?php
defined('BASEPATH') or exit('No direct script access allowed');

class C_kurikulum extends CI_Controller
{
    public function __construct()
    {
        parent::__construct();
        date_default_timezone_set("Asia/Jakarta");

        if (!$this->ion_auth->logged_in()) {
            redirect('auth/login', 'refresh');
        }

        $user_obj = $this->ion_auth->user()->row();
        $user_email = strtolower(trim($user_obj->email ?? ''));
        $user_uname = strtolower(trim($user_obj->username ?? ''));
        $is_gege = ($user_email === 'gege.satya@wbi.ac.id' || $user_uname === 'gege.satya@wbi.ac.id');

        // Untuk user dengan status group = 15, tidak bisa mengakses C_kurikulum kecuali akun dengan username gege.satya@wbi.ac.id
        if ($this->ion_auth->in_group(15) && !$is_gege) {
            redirect('auth/logout', 'refresh');
        }

        $this->load->model('Setting_api_key_model');
        $this->load->model('Maintenance_model');
        $this->load->library('Ai_reviewer');
        $this->_ensure_kurikulum_schema();

        // Cek mode maintenance untuk modul kurikulum
        if ($this->Maintenance_model->is_maintenance('kurikulum') && !$this->Maintenance_model->is_user_exempt()) {
            if ($this->input->is_ajax_request()) {
                $status = $this->Maintenance_model->get_status('kurikulum');
                $this->output->set_content_type('application/json');
                echo json_encode([
                    'status' => 'error',
                    'maintenance' => true,
                    'msg' => $status->message ?? 'Modul Kurikulum sedang dalam pemeliharaan sistem.'
                ]);
                exit;
            } else {
                $status = $this->Maintenance_model->get_status('kurikulum');
                $output['judul_besar'] = 'Pemeliharaan Sistem';
                $output['judul_kecil'] = 'Under Maintenance';
                $output['menu_aktif'] = 'm_kurikulum_list';
                $output['parent_ws'] = 'active open';
                $output['module_title'] = 'Modul Kurikulum & Audit CPL';
                $output['maintenance_message'] = $status->message ?? 'Modul Kurikulum sedang dalam pemeliharaan dan pembaruan sistem oleh Administrator Akademik.';
                $output['content'] = 'maintenance/v_maintenance_notice';
                $this->load->view('master_page', $output);
                $this->output->_display();
                exit;
            }
        }
    }

    /**
     * Auto-migrate missing columns in siakad_pustaka_kurikulum if running on fresh DB or another PC/hosting
     */
    private function _ensure_kurikulum_schema()
    {
        if (!$this->db->table_exists('siakad_pustaka_kurikulum')) {
            return;
        }

        $fields = $this->db->list_fields('siakad_pustaka_kurikulum');

        if (!in_array('normalized_json', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `normalized_json` LONGTEXT NULL");
        }
        if (!in_array('normalization_status', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `normalization_status` VARCHAR(50) DEFAULT 'NOT_NORMALIZED'");
        }
        if (!in_array('schema_version', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `schema_version` VARCHAR(20) DEFAULT '1.0'");
        }
        if (!in_array('parser_version', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `parser_version` VARCHAR(50) DEFAULT 'Phase-1.7'");
        }
        if (!in_array('source_hash', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `source_hash` VARCHAR(64) NULL");
        }
        if (!in_array('normalized_at', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `normalized_at` DATETIME NULL");
        }
    }

    /**
     * Helper to get permissions for current user (Kaprodi, Direktur, Wadir 1, SPMI vs Regular Lecturer)
     */
    private function get_user_permissions($id_ptk)
    {
        $is_admin = $this->ion_auth->is_admin() || $this->ion_auth->in_group(1) || $this->ion_auth->in_group(4);

        $user_obj = $this->ion_auth->user()->row();
        $user_email = strtolower(trim($user_obj->email ?? ''));
        $user_uname = strtolower(trim($user_obj->username ?? ''));
        $is_gege = ($user_email === 'gege.satya@wbi.ac.id' || $user_uname === 'gege.satya@wbi.ac.id');

        // Cek apakah user terdaftar sebagai Kaprodi di tabel kaprodi atau ion_auth group 5
        $kaprodi_rows = !empty($id_ptk) ? $this->db->where('id_ptk', $id_ptk)->get('kaprodi')->result() : [];
        $is_kaprodi = (!empty($kaprodi_rows) || $this->ion_auth->in_group(5) || $is_admin);

        // Cek roles Direktur, Wadir 1, dan SPMI dari tabel siakad_akses_data_center dan ion_auth groups
        $is_direktur = ($this->ion_auth->in_group(6) || $this->ion_auth->in_group('direktur'));
        $is_wadir1 = ($this->ion_auth->in_group(12) || $this->ion_auth->in_group('wadir1'));
        $is_spmi = ($this->ion_auth->in_group(8) || $this->ion_auth->in_group(18) || $this->ion_auth->in_group('spmi') || $this->ion_auth->in_group('simutu_admin'));

        if (!empty($user_email) || !empty($user_uname)) {
            $akses_rows = $this->db->group_start()
                ->where('username', $user_email)
                ->or_where('username', $user_uname)
                ->group_end()
                ->get('siakad_akses_data_center')->result();

            foreach ($akses_rows as $ar) {
                $r = strtolower(trim((string)$ar->roles));
                if ($r === 'direktur')
                    $is_direktur = true;
                if ($r === 'wadir1')
                    $is_wadir1 = true;
                if ($r === 'spmi')
                    $is_spmi = true;
            }
        }

        // Hak akses unggah & hapus: Khusus akun gege.satya@wbi.ac.id
        $can_upload = $is_gege;
        $can_delete = $is_gege;
        // Hak akses audit kurikulum umum
        $can_audit = ($is_admin || $is_kaprodi);

        $my_prodis = [];
        $my_sms_ids = [];
        foreach ($kaprodi_rows as $kr) {
            $my_prodis[] = strtolower(trim((string)$kr->nama));
            if (!empty($kr->id_sms)) {
                $my_sms_ids[] = $kr->id_sms;
            }
        }

        // Tentukan label role pengguna
        $role_label = 'Dosen';
        if ($is_admin)
            $role_label = 'Administrator';
        elseif ($is_direktur)
            $role_label = 'Direktur';
        elseif ($is_wadir1)
            $role_label = 'Wadir 1 (Akademik)';
        elseif ($is_spmi)
            $role_label = 'SPMI';
        elseif ($is_kaprodi)
            $role_label = 'Ketua Program Studi';

        return [
            'is_admin' => $is_admin,
            'is_kaprodi' => $is_kaprodi,
            'is_direktur' => $is_direktur,
            'is_wadir1' => $is_wadir1,
            'is_spmi' => $is_spmi,
            'can_audit' => $can_audit,
            'can_upload' => $can_upload,
            'can_delete' => $can_delete,
            'is_gege' => $is_gege,
            'role_label' => $role_label,
            'my_prodis' => $my_prodis,
            'my_sms_ids' => $my_sms_ids,
            'kaprodi_rows' => $kaprodi_rows
        ];
    }

    /**
     * Helper to get siakad_pustaka_kurikulum row with automatic file self-healing and persistent JSON restore
     */
    protected function _get_pustaka_row_with_autoheal($id)
    {
        $row = $this->db->where('id', (int) $id)->get('siakad_pustaka_kurikulum')->row();
        if (!$row) {
            return null;
        }

        $needs_update = false;
        $updates = [];

        $safe_slug = preg_replace('/[^a-zA-Z0-9_-]/', '_', $row->nama_prodi);
        $upload_dir = FCPATH . 'uploads/pustaka_kurikulum/';
        $config_dir = APPPATH . 'config/kurikulum_payloads/';

        if (!is_dir($config_dir)) {
            @mkdir($config_dir, 0777, true);
        }
        if (!is_dir($upload_dir)) {
            @mkdir($upload_dir, 0777, true);
        }

        // Normalize any absolute paths (e.g., C:/laragon/... or /var/www/...) to clean relative path
        if (!empty($row->file_path_doc)) {
            $cleaned_doc = str_replace('\\', '/', $row->file_path_doc);
            if (preg_match('#(uploads/pustaka_kurikulum/[^/]+)$#i', $cleaned_doc, $m_doc)) {
                if ($row->file_path_doc !== $m_doc[1]) {
                    $row->file_path_doc = $m_doc[1];
                    $updates['file_path_doc'] = $m_doc[1];
                    $needs_update = true;
                }
            }
        }
        if (!empty($row->file_path_content)) {
            $cleaned_content = str_replace('\\', '/', $row->file_path_content);
            if (preg_match('#(uploads/pustaka_kurikulum/[^/]+)$#i', $cleaned_content, $m_cnt)) {
                if ($row->file_path_content !== $m_cnt[1]) {
                    $row->file_path_content = $m_cnt[1];
                    $updates['file_path_content'] = $m_cnt[1];
                    $needs_update = true;
                }
            }
        }

        $doc_exists = !empty($row->file_path_doc) && file_exists(FCPATH . $row->file_path_doc);
        $txt_exists = !empty($row->file_path_content) && file_exists(FCPATH . $row->file_path_content);

        if (!$doc_exists) {
            $doc_files = glob($upload_dir . 'doc_' . $safe_slug . '_*.*');
            if (!empty($doc_files)) {
                usort($doc_files, fn($a, $b) => filemtime($b) - filemtime($a));
                $latest_doc = 'uploads/pustaka_kurikulum/' . basename($doc_files[0]);
                $row->file_path_doc = $latest_doc;
                $updates['file_path_doc'] = $latest_doc;
                $doc_exists = true;
                $needs_update = true;
            }
        }

        if (!$txt_exists) {
            $txt_files = glob($upload_dir . 'content_' . $safe_slug . '_*.md');
            if (!empty($txt_files)) {
                usort($txt_files, fn($a, $b) => filemtime($b) - filemtime($a));
                $latest_txt = 'uploads/pustaka_kurikulum/' . basename($txt_files[0]);
                $row->file_path_content = $latest_txt;
                $updates['file_path_content'] = $latest_txt;
                $row->total_karakter = filesize($txt_files[0]);
                $updates['total_karakter'] = $row->total_karakter;
                $txt_exists = true;
                $needs_update = true;
            }
        }

        $cfg_json = $config_dir . 'normalized_' . $safe_slug . '.json';
        $upl_json = $upload_dir . 'normalized_' . $safe_slug . '.json';

        $has_db_norm = !empty($row->normalized_json) && !empty($row->normalization_status) && $row->normalization_status !== 'NOT_NORMALIZED';

        if (!$has_db_norm) {
            // Cek apakah ada file JSON tersimpan di disk (baik di config maupun uploads)
            $json_disk_file = file_exists($cfg_json) ? $cfg_json : (file_exists($upl_json) ? $upl_json : null);

            if ($json_disk_file && file_exists($json_disk_file)) {
                $raw_json = file_get_contents($json_disk_file);
                $decoded = json_decode($raw_json, true);
                if (!empty($decoded) && is_array($decoded)) {
                    $norm_status = $decoded['curriculum']['verification_status'] ?? ($decoded['normalization_status'] ?? 'VERIFIED');
                    if (empty($norm_status) || $norm_status === 'NOT_NORMALIZED') {
                        $norm_status = 'VERIFIED';
                    }
                    $source_hash = $decoded['curriculum']['source_hash'] ?? ($decoded['source_hash'] ?? '');

                    $updates['normalized_json'] = $raw_json;
                    $updates['normalization_status'] = $norm_status;
                    $updates['schema_version'] = $decoded['schema_version'] ?? '1.0';
                    $updates['parser_version'] = $decoded['metadata']['parser_version'] ?? 'Phase-1.7';
                    $updates['source_hash'] = $source_hash;
                    $updates['normalized_at'] = $decoded['curriculum']['verified_at'] ?? date('Y-m-d H:i:s');

                    $row->normalized_json = $raw_json;
                    $row->normalization_status = $norm_status;
                    $row->schema_version = $updates['schema_version'];
                    $row->parser_version = $updates['parser_version'];
                    $row->source_hash = $source_hash;
                    $row->normalized_at = $updates['normalized_at'];
                    $needs_update = true;

                    // Pastikan kedua file disk sinkron
                    if (!file_exists($cfg_json))
                        @file_put_contents($cfg_json, $raw_json);
                    if (!file_exists($upl_json))
                        @file_put_contents($upl_json, $raw_json);
                }
            } elseif ($txt_exists && file_exists(FCPATH . $row->file_path_content)) {
                // Auto-normalize dari content file jika belum pernah ada JSON
                $doc_content = file_get_contents(FCPATH . $row->file_path_content);
                $doc_info = [
                    'judul_dokumen' => $row->judul_dokumen,
                    'tahun_kurikulum' => $row->tahun_kurikulum,
                    'file_name' => $row->file_name
                ];
                $payload = $this->_build_structured_curriculum_library($doc_content, $row->nama_prodi, $doc_info);
                $validation = $this->_validate_structured_curriculum_library($payload);
                if ($validation['valid']) {
                    $payload['curriculum']['verification_status'] = 'VERIFIED';
                    $payload['curriculum']['verified_at'] = date('Y-m-d H:i:s');
                    $payload['curriculum']['verified_by'] = 'gege.satya@wbi.ac.id';

                    $raw_json = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                    $source_hash = $payload['curriculum']['source_hash'] ?? '';

                    $updates['normalized_json'] = $raw_json;
                    $updates['normalization_status'] = 'VERIFIED';
                    $updates['schema_version'] = '1.0';
                    $updates['parser_version'] = $payload['metadata']['parser_version'] ?? 'Phase-1.7';
                    $updates['source_hash'] = $source_hash;
                    $updates['normalized_at'] = date('Y-m-d H:i:s');

                    $row->normalized_json = $raw_json;
                    $row->normalization_status = 'VERIFIED';
                    $row->schema_version = '1.0';
                    $row->parser_version = $updates['parser_version'];
                    $row->source_hash = $source_hash;
                    $row->normalized_at = $updates['normalized_at'];
                    $needs_update = true;

                    @file_put_contents($cfg_json, $raw_json);
                    @file_put_contents($upl_json, $raw_json);
                }
            }
        } else {
            // Jika di DB sudah ada normalized_json, pastikan tersimpan ke disk juga agar terbawa saat pindah PC / hosting
            if (!file_exists($cfg_json)) {
                @file_put_contents($cfg_json, $row->normalized_json);
            }
            if (!file_exists($upl_json)) {
                @file_put_contents($upl_json, $row->normalized_json);
            }
        }

        if ($needs_update) {
            $this->db->where('id', $row->id)->update('siakad_pustaka_kurikulum', $updates);
        }

        return $row;
    }

    public function index()
    {
        $id_ptk = $this->session->userdata('id_ptk');
        $api_setting = $this->Setting_api_key_model->get_api_key($id_ptk);

        $provider = $api_setting->ai_provider ?? 'gemini';
        $has_api_key = !empty($api_setting) && !empty($api_setting->api_key);

        // Permissions
        $perms = $this->get_user_permissions($id_ptk);

        // Ambil daftar Program Studi dari tabel sms
        $sms_query = $this->db->select('id_sms, nm_lemb')->from('sms')->order_by('nm_lemb', 'ASC')->get();
        $prodi_list = [];
        if ($sms_query && $sms_query->num_rows() > 0) {
            foreach ($sms_query->result() as $row) {
                if (stripos($row->nm_lemb, 'Politeknik') === false && stripos($row->nm_lemb, 'Direktorat') === false && stripos($row->nm_lemb, 'Bagian') === false) {
                    $prodi_list[$row->nm_lemb] = $row->nm_lemb;
                }
            }
        }
        if (empty($prodi_list)) {
            $prodi_list = [
                'D4 Manajemen Perusahaan Internasional (MPI)' => 'D4 Manajemen Perusahaan Internasional (MPI)',
                'D4 Akuntansi Perpajakan (AP)' => 'D4 Akuntansi Perpajakan (AP)',
                'D4 Agribisnis Hortikultura (AH)' => 'D4 Agribisnis Hortikultura (AH)',
                'D4 Pengelolaan Konvensi dan Acara (PKA)' => 'D4 Pengelolaan Konvensi dan Acara (PKA)',
                'D4 Teknologi Rekayasa Perangkat Lunak (TRPL)' => 'D4 Teknologi Rekayasa Perangkat Lunak (TRPL)'
            ];
        }

        // Ambil daftar seluruh dokumen kurikulum
        $kurikulum_list = $this->db->order_by('nama_prodi', 'ASC')->get('siakad_pustaka_kurikulum')->result();

        // Auto-heal / backfill jika ada record yang file path atau tahun_kurikulum nya bermasalah
        foreach ($kurikulum_list as &$k_item) {
            $healed = $this->_get_pustaka_row_with_autoheal($k_item->id);
            if ($healed) {
                $k_item = $healed;
            }

            if (empty($k_item->tahun_kurikulum) || $k_item->tahun_kurikulum === '-') {
                $doc_content = '';
                if (!empty($k_item->file_path_content) && file_exists(FCPATH . $k_item->file_path_content)) {
                    $doc_content = file_get_contents(FCPATH . $k_item->file_path_content);
                }
                $extracted_yr = $this->extract_tahun_kurikulum($k_item->file_name, $k_item->judul_dokumen, $doc_content);
                $k_item->tahun_kurikulum = $extracted_yr;
                $this->db->where('id', $k_item->id)->update('siakad_pustaka_kurikulum', ['tahun_kurikulum' => $extracted_yr]);
            }
        }
        unset($k_item);

        $output['judul_besar'] = 'Daftar Kurikulum & Audit OBE';
        $output['judul_kecil'] = 'SN-Dikti Permendiktisaintek No. 39/2025 jo No. 10/2026';
        $output['menu_aktif'] = 'm_kurikulum_list';
        $output['parent_ws'] = 'active open';
        $output['content'] = 'kurikulum/v_kurikulum_list';
        $output['after_page'] = 'kurikulum/v_kurikulum_list_after_page';

        $output['ai_provider'] = $provider;
        $output['has_api_key'] = $has_api_key;
        $output['prodi_list'] = $prodi_list;
        $output['kurikulum_list'] = $kurikulum_list;
        $output['is_kaprodi'] = $perms['is_kaprodi'];
        $output['is_admin'] = $perms['is_admin'];
        $output['is_direktur'] = $perms['is_direktur'];
        $output['is_wadir1'] = $perms['is_wadir1'];
        $output['is_spmi'] = $perms['is_spmi'];
        $output['can_audit'] = $perms['can_audit'];
        $output['can_upload'] = $perms['can_upload'];
        $output['can_delete'] = $perms['can_delete'];
        $output['is_gege'] = $perms['is_gege'];
        $output['user_role_label'] = $perms['role_label'];
        $output['my_kaprodi_prodis'] = $perms['my_prodis'];
        $output['my_kaprodi_sms_ids'] = $perms['my_sms_ids'];
        $output['kaprodi_names_str'] = implode(', ', array_map(fn($r) => $r->nama, $perms['kaprodi_rows']));

        $output['maintenance_statuses'] = $this->Maintenance_model->get_all_statuses();
        $output['is_maintenance_kurikulum'] = $this->Maintenance_model->is_maintenance('kurikulum');
        $output['is_maintenance_studio_rps'] = $this->Maintenance_model->is_maintenance('studio_rps');

        $this->load->view('master_page', $output);
    }

    /**
     * Download Berkas PDF Dokumen Kurikulum
     */
    public function download($id = null)
    {
        $id = (int) $id;
        $row = $this->_get_pustaka_row_with_autoheal($id);

        if (!$row || empty($row->file_path_doc) || !file_exists(FCPATH . $row->file_path_doc)) {
            show_404();
            return;
        }

        $this->load->helper('download');
        $file_path = FCPATH . $row->file_path_doc;
        $file_name = !empty($row->file_name) ? $row->file_name : basename($file_path);

        force_download($file_name, file_get_contents($file_path));
    }

    /**
     * AJAX: Upload & Parse Berkas Kurikulum (PDF/DOCX/TXT/MD) - Khusus akun gege.satya@wbi.ac.id
     */
    public function ajax_upload()
    {
        $this->output->set_content_type('application/json');

        $id_ptk = $this->session->userdata('id_ptk');
        $perms = $this->get_user_permissions($id_ptk);

        if (!$perms['can_upload']) {
            echo json_encode([
                'status' => false,
                'msg' => 'Akses ditolak. Fitur unggah dan perbarui dokumen kurikulum hanya dibuka untuk akun gege.satya@wbi.ac.id.'
            ]);
            return;
        }

        if (empty($_FILES['doc_file']['name'])) {
            echo json_encode(['status' => false, 'msg' => 'Tidak ada file yang diunggah.']);
            return;
        }

        $file_name = trim($_FILES['doc_file']['name']);
        $file_tmp = $_FILES['doc_file']['tmp_name'];
        $file_ext = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));

        $allowed_exts = ['pdf', 'docx', 'txt', 'rtf', 'md'];
        if (!in_array($file_ext, $allowed_exts)) {
            echo json_encode(['status' => false, 'msg' => 'Format file tidak didukung. Harap unggah file PDF, DOCX, TXT, atau MD.']);
            return;
        }

        // Validasi Duplikasi Nama File: Cek apakah nama file yang sama persis sudah pernah diunggah
        $duplicate = $this->db->where('file_name', $file_name)->get('siakad_pustaka_kurikulum')->row();
        if ($duplicate) {
            echo json_encode([
                'status' => false,
                'msg' => 'Berkas dengan nama "' . htmlspecialchars($file_name) . '" sudah pernah diunggah sebelumnya (Prodi: ' . htmlspecialchars($duplicate->nama_prodi) . ' pada ' . date('d M Y, H:i', strtotime($duplicate->created_at)) . '). Harap gunakan nama berkas yang berbeda atau hapus dokumen lama terlebih dahulu.'
            ]);
            return;
        }

        $nama_prodi = trim($this->input->post('nama_prodi', true));
        $judul_dokumen = trim($this->input->post('judul_dokumen', true));

        if (empty($nama_prodi)) {
            echo json_encode(['status' => false, 'msg' => 'Program Studi wajib dipilih.']);
            return;
        }

        if (empty($judul_dokumen)) {
            $judul_dokumen = 'Dokumen Kurikulum & CPL ' . $nama_prodi;
        }

        $extracted_text = '';
        try {
            if ($file_ext === 'pdf') {
                $parser = new \Smalot\PdfParser\Parser();
                $pdf = $parser->parseFile($file_tmp);
                $extracted_text = $pdf->getText();
            } elseif ($file_ext === 'docx') {
                $extracted_text = $this->extract_docx_text($file_tmp);
            } else {
                $extracted_text = file_get_contents($file_tmp);
            }
        } catch (Exception $e) {
            echo json_encode(['status' => false, 'msg' => 'Gagal membaca dokumen: ' . $e->getMessage()]);
            return;
        }

        $extracted_text = trim($extracted_text);
        if (empty($extracted_text)) {
            echo json_encode([
                'status' => false,
                'msg' => 'Dokumen kosong atau teks tidak terbaca (jika PDF, pastikan bukan hasil scan tanpa OCR).'
            ]);
            return;
        }

        // Ekstrak Tahun Kurikulum Secara Otomatis dari nama file dan naskah dokumen
        $tahun_kurikulum = $this->extract_tahun_kurikulum($file_name, $judul_dokumen, $extracted_text);

        $upload_dir = FCPATH . 'uploads/pustaka_kurikulum/';
        if (!is_dir($upload_dir)) {
            @mkdir($upload_dir, 0777, true);
        }

        $safe_slug = preg_replace('/[^a-zA-Z0-9_-]/', '_', $nama_prodi);
        $ts = time();
        $orig_saved_name = 'doc_' . $safe_slug . '_' . $ts . '.' . $file_ext;
        $text_saved_name = 'content_' . $safe_slug . '_' . $ts . '.md';

        @copy($file_tmp, $upload_dir . $orig_saved_name);
        @file_put_contents($upload_dir . $text_saved_name, $extracted_text);

        $user_name = $this->session->userdata('nama') ?: ($this->ion_auth->user()->row()->first_name ?? 'Dosen');

        $data_pustaka = [
            'nama_prodi' => $nama_prodi,
            'judul_dokumen' => $judul_dokumen,
            'tahun_kurikulum' => $tahun_kurikulum,
            'file_name' => $file_name,
            'file_path_doc' => 'uploads/pustaka_kurikulum/' . $orig_saved_name,
            'file_path_content' => 'uploads/pustaka_kurikulum/' . $text_saved_name,
            'total_karakter' => strlen($extracted_text),
            'uploaded_by_ptk' => $id_ptk,
            'uploaded_by_nama' => $user_name,
            'updated_at' => date('Y-m-d H:i:s')
        ];

        $exist = $this->db->where('nama_prodi', $nama_prodi)->get('siakad_pustaka_kurikulum')->row();
        if ($exist) {
            $this->db->where('id', $exist->id)->update('siakad_pustaka_kurikulum', $data_pustaka);
            $pustaka_id = $exist->id;
            $msg = 'Dokumen Kurikulum untuk Prodi ' . $nama_prodi . ' (Tahun ' . $tahun_kurikulum . ') berhasil diperbarui!';
        } else {
            $data_pustaka['created_at'] = date('Y-m-d H:i:s');
            $this->db->insert('siakad_pustaka_kurikulum', $data_pustaka);
            $pustaka_id = $this->db->insert_id();
            $msg = 'Dokumen Kurikulum untuk Prodi ' . $nama_prodi . ' berhasil diunggah!';
        }

        echo json_encode([
            'status' => true,
            'msg' => $msg,
            'pustaka_id' => $pustaka_id,
            'char_count' => strlen($extracted_text)
        ]);
    }

    /**
     * AJAX: Ambil Isi Teks Kurikulum (Dapat diakses seluruh dosen)
     */
    public function ajax_get_content()
    {
        $this->output->set_content_type('application/json');
        $id = (int) $this->input->post('id', true);
        $row = $this->_get_pustaka_row_with_autoheal($id);

        if ($row && !empty($row->file_path_content) && file_exists(FCPATH . $row->file_path_content)) {
            $content = file_get_contents(FCPATH . $row->file_path_content);
            echo json_encode([
                'status' => true,
                'data' => [
                    'id' => $row->id,
                    'nama_prodi' => $row->nama_prodi,
                    'judul_dokumen' => $row->judul_dokumen,
                    'tahun_kurikulum' => $row->tahun_kurikulum,
                    'file_name' => $row->file_name,
                    'file_path_doc' => base_url($row->file_path_doc),
                    'total_karakter' => (int) $row->total_karakter,
                    'uploaded_by_nama' => $row->uploaded_by_nama,
                    'updated_at' => date('d M Y, H:i', strtotime($row->updated_at ?: $row->created_at)),
                    'content' => $content
                ]
            ]);
            return;
        }

        echo json_encode(['status' => false, 'msg' => 'Berkas naskah kurikulum tidak ditemukan di server.']);
    }

    /**
     * AJAX: Hapus Dokumen Kurikulum (Khusus akun gege.satya@wbi.ac.id)
     */
    public function ajax_delete()
    {
        $this->output->set_content_type('application/json');
        $id = (int) $this->input->post('id', true);
        $row = $this->_get_pustaka_row_with_autoheal($id);

        if (!$row) {
            echo json_encode(['status' => false, 'msg' => 'Data kurikulum tidak ditemukan.']);
            return;
        }

        $id_ptk = $this->session->userdata('id_ptk');
        $perms = $this->get_user_permissions($id_ptk);

        if (!$perms['can_delete']) {
            echo json_encode([
                'status' => false,
                'msg' => 'Akses ditolak. Fitur hapus dokumen kurikulum hanya dibuka untuk akun gege.satya@wbi.ac.id.'
            ]);
            return;
        }

        if (!empty($row->file_path_doc) && file_exists(FCPATH . $row->file_path_doc)) {
            @unlink(FCPATH . $row->file_path_doc);
        }
        if (!empty($row->file_path_content) && file_exists(FCPATH . $row->file_path_content)) {
            @unlink(FCPATH . $row->file_path_content);
        }

        $this->db->where('id', $id)->delete('siakad_pustaka_kurikulum');

        echo json_encode(['status' => true, 'msg' => 'Dokumen kurikulum prodi ' . $row->nama_prodi . ' berhasil dihapus.']);
    }

