            ]);
            return;
        }

        // =========================================================================
        // SYSTEM PROMPT AUDIT KURIKULUM OBE (STANDAR GEMINI & OPENAI)
        // =========================================================================
        $system_prompt = "Anda adalah Auditor Senior Kurikulum Outcome-Based Education (OBE) dan Penjaminan Mutu Pendidikan Tinggi Indonesia.\n\n";
        $system_prompt .= "### REGULASI & STANDAR ACUAN:\n";
