        $system_prompt .= "- **Distribusi Bahan Kajian terhadap CPL:** [Evaluasi apakah seluruh CPL didukung bahan kajian yang relevan]\n";
        $system_prompt .= "- **Peta Alignment Mata Kuliah:** [Evaluasi sebaran mata kuliah per semester]\n";
        $system_prompt .= "- **Kesesuaian Beban SKS (1 SKS = 45 Jam):** [Evaluasi proporsi teori vs praktikum/proyek]\n\n";
        $system_prompt .= "## 5. REKOMENDASI PERBAIKAN & RENCANA TINDAK LANJUT (SIKLUS PPEPP)\n";
        $system_prompt .= "| Aspek Kurikulum | Akar Masalah / Temuan Gap | Rekomendasi Tindak Lanjut | Prioritas |\n";
        $system_prompt .= "|---|---|---|---|\n";
        $system_prompt .= "| Rumusan CPL | [Temuan gap] | [Rekomendasi konkret] | [Tinggi / Sedang] |\n";
        $system_prompt .= "| Bahan Kajian | [Temuan gap] | [Rekomendasi konkret] | [Tinggi / Sedang] |\n";
        $system_prompt .= "| Matriks Penilaian | [Temuan gap] | [Rekomendasi konkret] | [Tinggi / Sedang] |\n\n";
        $system_prompt .= "## 6. KESIMPULAN & STATUS KESIAPAN DOKUMEN\n";
        $system_prompt .= "[Paragraf evaluasi kesiapan implementasi dokumen kurikulum ke RPS OBE dan akreditasi BAN-PT/LAM]";

        $user_document = "## DOKUMEN KURIKULUM RESMI YANG DIAUDIT:\n";
        $user_document .= "- Program Studi: " . $row->nama_prodi . "\n";
        $user_document .= "- Judul Dokumen: " . $row->judul_dokumen . "\n";
        $user_document .= "- Total Karakter: " . strlen($content) . "\n\n";
        $user_document .= "```markdown\n" . substr($content, 0, 50000) . "\n```\n\n";
        $user_document .= "Lakukan audit kepatuhan OBE sekarang. Ikuti format persis di atas.";

        $ai_result = $this->ai_reviewer->generate_review(
            $provider,
            $api_key,
            $system_prompt,
            $user_document,
            false,
            false,
            $model
        );

        if (!$ai_result['status']) {
            echo json_encode(['status' => false, 'msg' => $ai_result['msg']]);
            return;
        }

        $user_name = $this->session->userdata('nama') ?: ($this->ion_auth->user()->row()->first_name ?? 'Auditor');
        $auditor_nama = $user_name . ' (' . $perms['role_label'] . ')';

        $review_text = trim($ai_result['review']);

        // 1. Bersihkan tag <think>...</think> (DeepSeek-R1 / Reasoner)
        $review_text = preg_replace('/<think>[\s\S]*?<\/think>/i', '', $review_text);
        $review_text = trim($review_text);

        // 2. Normalisasi & Sanitisasi Output (Menghilangkan code fence jika DeepSeek / OpenAI menyertakannya)
        if (preg_match('/^```(?:markdown)?\s*\n([\s\S]*?)\n```$/i', $review_text, $m)) {
            $review_text = trim($m[1]);
        } else {
            $review_text = preg_replace('/^```(?:markdown)?\s*/i', '', $review_text);
            $review_text = preg_replace('/\s*```$/i', '', $review_text);
        }

        // Hilangkan preamble jika ada teks pengantar sebelum judul utama
        $pos = stripos($review_text, '# LAPORAN AUDIT');
        if ($pos !== false && $pos > 0) {
            $review_text = substr($review_text, $pos);
        }

        // Ekstrak Skor Kepatuhan & Kesimpulan Singkat
        $skor_kepatuhan = '';
        if (preg_match('/\*\*Skor Kepatuhan OBE Keseluruhan:\*\*\s*([^\n\r]+)/i', $review_text, $m)) {
            $skor_kepatuhan = trim($m[1]);
        }

        $kesimpulan_singkat = '';
        if (preg_match('/##\s*6\.\s*KESIMPULAN[^\n\r]*\n+([^\n\r#]+)/i', $review_text, $m)) {
            $kesimpulan_singkat = trim($m[1]);
        } elseif (preg_match('/##\s*KESIMPULAN[^\n\r]*\n+([^\n\r#]+)/i', $review_text, $m)) {
            $kesimpulan_singkat = trim($m[1]);
        } else {
            $clean_txt = preg_replace('/[#*`\-_]/', ' ', $review_text);
            $clean_txt = preg_replace('/\s+/', ' ', trim($clean_txt));
            $kesimpulan_singkat = substr($clean_txt, 0, 180) . '...';
        }

        if (!empty($skor_kepatuhan)) {
            $kesimpulan_singkat = '<strong>' . htmlspecialchars($skor_kepatuhan) . '</strong> — ' . $kesimpulan_singkat;
        }

        // Simpan ke database siakad_pustaka_kurikulum
        $data_audit = [
            'audit_terakhir_at' => date('Y-m-d H:i:s'),
            'audit_oleh_ptk' => $id_ptk,
            'audit_oleh_nama' => $auditor_nama,
            'audit_kesimpulan' => $kesimpulan_singkat,
            'audit_full_result' => $review_text
        ];
        $this->db->where('id', $id)->update('siakad_pustaka_kurikulum', $data_audit);

        echo json_encode([
            'status' => true,
            'nama_prodi' => $row->nama_prodi,
            'audit_oleh_nama' => $auditor_nama,
            'audit_terakhir_at' => date('d M Y, H:i') . ' WIB',
            'kesimpulan_singkat' => $kesimpulan_singkat,
            'audit_text' => $review_text
        ]);
    }

