    /**
     * Helper to read plain text from DOCX
     */
    private function extract_docx_text($filename)
    {
        $text = '';
        $zip = new ZipArchive();
        if ($zip->open($filename) === TRUE) {
            $xml_index = $zip->locateName('word/document.xml');
            if ($xml_index !== false) {
                $xml_data = $zip->getFromIndex($xml_index);
                $xml_data = str_replace('</w:p>', "\n", $xml_data);
                $xml_data = str_replace('</w:tr>', "\n", $xml_data);
                $xml_data = str_replace('</w:tc>', "\t", $xml_data);
                $text = strip_tags($xml_data);
            }
            $zip->close();
        }
        return $text;
    }

    /**
     * Helper to intelligently extract curriculum year from filename, document title, and text content
     */
    private function extract_tahun_kurikulum($file_name, $judul_dokumen, $text)
    {
        // 1. Cek tahun dari nama file (paling akurat untuk versi/edisi berkas yang diunggah)
        if (preg_match('/(?:^|[^0-9])(20[123]\d)(?:[^0-9]|$)/', $file_name, $m)) {
            return $m[1];
        }

        // 2. Cek tahun dari judul dokumen jika ada
        if (!empty($judul_dokumen) && preg_match('/(?:^|[^0-9])(20[123]\d)(?:[^0-9]|$)/', $judul_dokumen, $m)) {
            return $m[1];
        }

        // 3. Cek naskah dokumen pada 5000 karakter pertama (cover / SK / identitas)
        $head = substr($text, 0, 5000);

        // Pola A: "K -DIKTI) 2023", "KURIKULUM PENDIDIKAN TINGGI ... 2023", "KURIKULUM 2024"
        if (preg_match('/(?:k[\s\-]*dikti|kpt|kurikulum|edisi|revisi)\s*[\(\)\:]*\s*(20[123]\d)/i', $head, $m)) {
            return $m[1];
        }

        // Pola B: "TAHUN 202X" di cover/header
        if (preg_match('/(?:^|\n|\r)[^\n\r]*\bTAHUN\s+(20[123]\d)\b/i', $head, $m)) {
            return $m[1];
        }

        // Pola C: SK atau pendirian Prodi (e.g., 081/D/OT/2021)
        if (preg_match('/(?:nomor|no\.?)[^\n\r]+?\/(20[123]\d)\b/i', $head, $m)) {
            return $m[1];
        }

        // Pola D: Angka tahun 2018-2030 yang pertama kali muncul di awal dokumen
        if (preg_match('/(?:^|[^0-9])(20(?:1[89]|2[0-9]|30))(?:[^0-9]|$)/', $head, $m)) {
            return $m[1];
        }

        return date('Y');
    }

    // =========================================================================
    // PHASE 1.7 — STRUCTURED CURRICULUM NORMALIZATION, VERIFY, REBUILD & SUMMARY
    // =========================================================================

    /**
     * AJAX: Normalisasi Kurikulum (Khusus akun gege.satya@wbi.ac.id)
     * Menjalankan parser + normalisasi deterministik dan menyimpan normalized_json dengan status NORMALIZED.
     * Tidak auto-VERIFY agar admin melakukan verifikasi eksplisit.
     */
    public function ajax_normalize_curriculum()
    {
        $this->output->set_content_type('application/json');

        $id_ptk = $this->session->userdata('id_ptk');
        $perms = $this->get_user_permissions($id_ptk);

        if (!$perms['can_upload']) { // Khusus akun gege.satya@wbi.ac.id
            echo json_encode([
                'status' => false,
                'msg' => 'Akses ditolak. Fitur normalisasi kurikulum hanya dibuka untuk akun gege.satya@wbi.ac.id.'
            ]);
            return;
        }

        $id = (int) $this->input->post('id', true);
        $row = $this->_get_pustaka_row_with_autoheal($id);

        if (!$row || empty($row->file_path_content) || !file_exists(FCPATH . $row->file_path_content)) {
            echo json_encode(['status' => false, 'msg' => 'Berkas naskah kurikulum tidak ditemukan di server.']);
            return;
        }

        $content = file_get_contents(FCPATH . $row->file_path_content);
        $doc_info = [
            'judul_dokumen' => $row->judul_dokumen,
            'tahun_kurikulum' => $row->tahun_kurikulum,
            'file_name' => $row->file_name
        ];

        $payload = $this->_build_structured_curriculum_library($content, $row->nama_prodi, $doc_info);
        $validation = $this->_validate_structured_curriculum_library($payload);

        // Simpan dengan status NORMALIZED (JANGAN auto-VERIFY)
        $save_res = $this->_save_structured_curriculum_library($row->id, $payload, 'NORMALIZED');

        if (!$save_res['status']) {
            echo json_encode([
                'status' => false,
                'msg' => 'Normalisasi gagal disimpan: ' . $save_res['msg'],
                'errors' => $validation['errors']
            ]);
            return;
        }

        echo json_encode([
            'status' => true,
            'msg' => 'Normalisasi berhasil! Payload terstruktur telah disimpan dengan status NORMALIZED. Silakan review hasil dan klik Verifikasi jika sudah sesuai.',
            'summary' => [
                'official_cpl_count' => count($payload['official_cpl']),
                'bk_count' => count($payload['bahan_kajian']),
                'cpl_bk_status' => $payload['cpl_bk_mapping']['status'],
                'cpl_bk_count' => $payload['cpl_bk_mapping']['mappable_count'],
                'direct_cpl_mk' => count($payload['direct_cpl_mk_pairs']),
                'mk_count' => count($payload['mata_kuliah'])
            ],
            'validation' => $validation
        ]);
    }

    /**
     * AJAX: Verifikasi Pustaka Kurikulum (Khusus akun gege.satya@wbi.ac.id)
     * Hanya aktif jika payload lolos validation; mengubah status menjadi VERIFIED.
     */
    public function ajax_verify_curriculum()
    {
        $this->output->set_content_type('application/json');

        $id_ptk = $this->session->userdata('id_ptk');
        $perms = $this->get_user_permissions($id_ptk);

        if (!$perms['can_upload']) {
            echo json_encode([
                'status' => false,
                'msg' => 'Akses ditolak. Fitur verifikasi kurikulum hanya dibuka untuk akun gege.satya@wbi.ac.id.'
            ]);
            return;
        }

        $id = (int) $this->input->post('id', true);
        $row = $this->_get_pustaka_row_with_autoheal($id);

        if (!$row || empty($row->normalized_json)) {
            echo json_encode(['status' => false, 'msg' => 'Data terstruktur belum pernah dinormalisasi. Lakukan normalisasi terlebih dahulu.']);
            return;
        }

        $payload = json_decode($row->normalized_json, true);
        $validation = $this->_validate_structured_curriculum_library($payload);

        if (!$validation['valid']) {
            echo json_encode([
                'status' => false,
                'msg' => 'Pustaka kurikulum tidak dapat diverifikasi karena belum lolos validasi: ' . implode('; ', $validation['errors'])
            ]);
            return;
        }

        $payload['curriculum']['verification_status'] = 'VERIFIED';
        $payload['curriculum']['verified_at'] = date('Y-m-d H:i:s');
        $payload['curriculum']['verified_by'] = 'gege.satya@wbi.ac.id';

        $this->db->where('id', $row->id)->update('siakad_pustaka_kurikulum', [
            'normalization_status' => 'VERIFIED',
            'normalized_json' => json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
            'updated_at' => date('Y-m-d H:i:s')
        ]);

        echo json_encode([
            'status' => true,
            'msg' => 'Pustaka kurikulum prodi ' . $row->nama_prodi . ' berhasil diverifikasi (VERIFIED) dan siap digunakan sebagai factual grounding RPS!'
        ]);
    }

    /**
     * AJAX: Bangun Ulang Data Terstruktur (Khusus akun gege.satya@wbi.ac.id)
     * Menghitung ulang source_hash, menjalankan normalizer ulang, dan menset status NORMALIZED.
     */
    public function ajax_rebuild_curriculum()
    {
        $this->output->set_content_type('application/json');

        $id_ptk = $this->session->userdata('id_ptk');
        $perms = $this->get_user_permissions($id_ptk);

        if (!$perms['can_upload']) {
            echo json_encode([
                'status' => false,
                'msg' => 'Akses ditolak. Fitur bangun ulang data terstruktur hanya dibuka untuk akun gege.satya@wbi.ac.id.'
            ]);
            return;
        }

        $id = (int) $this->input->post('id', true);
        $row = $this->_get_pustaka_row_with_autoheal($id);

        if (!$row || empty($row->file_path_content) || !file_exists(FCPATH . $row->file_path_content)) {
            echo json_encode(['status' => false, 'msg' => 'Berkas sumber kurikulum tidak ditemukan di server.']);
            return;
        }

        $content = file_get_contents(FCPATH . $row->file_path_content);
        $doc_info = [
            'judul_dokumen' => $row->judul_dokumen,
            'tahun_kurikulum' => $row->tahun_kurikulum,
            'file_name' => $row->file_name
        ];

        $payload = $this->_build_structured_curriculum_library($content, $row->nama_prodi, $doc_info);
        $validation = $this->_validate_structured_curriculum_library($payload);

        $mk_count = count($payload['mata_kuliah'] ?? []);
        $tot_sks = 0;
        foreach (($payload['mata_kuliah'] ?? []) as $mk_item) {
            $tot_sks += (int)($mk_item['sks_total'] ?? 0);
        }
        $dir_pair_count = count($payload['direct_cpl_mk_pairs'] ?? []);
        $mapped_mk_count = 0;
        foreach (($payload['mata_kuliah'] ?? []) as $mk_item) {
            if (!empty($mk_item['effective_cpl_codes']) || !empty($mk_item['aggregate_domains'])) {
                $mapped_mk_count++;
            }
        }

        // Verification Gate for Akuntansi Perpajakan (Phase 1.7 Production Invariant)
        $is_ap_rebuild = (stripos($row->nama_prodi, 'Akuntansi') !== false || stripos($row->nama_prodi, 'Perpajakan') !== false);
        if ($is_ap_rebuild) {
            $expected_restored = ['402273', '502363', '588402'];
            $mk_codes = array_column($payload['mata_kuliah'] ?? [], 'kode_mk');
            $missing_restored = array_diff($expected_restored, $mk_codes);

            if ($mk_count !== 50 || $tot_sks !== 148 || $dir_pair_count !== 182 || $mapped_mk_count !== 50 || !empty($missing_restored)) {
                echo json_encode([
                    'status' => false,
                    'msg' => 'Verification Gate Failure (Akuntansi Perpajakan): MK=' . $mk_count . ' (harus 50), SKS=' . $tot_sks . ' (harus 148), DirectPairs=' . $dir_pair_count . ' (harus 182), MappedMK=' . $mapped_mk_count . ' (harus 50), MissingRestored=' . implode(',', $missing_restored),
                    'diagnostics' => [
                        'mata_kuliah_count' => $mk_count,
                        'total_sks' => $tot_sks,
                        'direct_cpl_mk_pair_count' => $dir_pair_count,
                        'mapped_course_count' => $mapped_mk_count,
                        'missing_restored_courses' => array_values($missing_restored)
                    ]
                ]);
                return;
            }
        }

        // Verification Gate for Pengelolaan Konvensi dan Acara (Phase 1.7 Production Invariant)
        $is_pka_rebuild = (stripos($row->nama_prodi, 'Konvensi') !== false || stripos($row->nama_prodi, 'Acara') !== false);
        if ($is_pka_rebuild) {
            $outside_mks = 0;
            foreach (($payload['mata_kuliah'] ?? []) as $mk_item) {
                if (($mk_item['effective_mapping_type'] ?? '') === 'ACTIVE_COURSE_OUTSIDE_CPL_MATRIX') {
                    $outside_mks++;
                }
            }
            if ($mk_count !== 50 || $tot_sks !== 144 || $dir_pair_count !== 551 || $mapped_mk_count !== 48 || $outside_mks !== 2) {
                echo json_encode([
                    'status' => false,
                    'msg' => 'Verification Gate Failure (Pengelolaan Konvensi dan Acara): MK=' . $mk_count . ' (harus 50), SKS=' . $tot_sks . ' (harus 144), DirectPairs=' . $dir_pair_count . ' (harus 551), MappedMK=' . $mapped_mk_count . ' (harus 48), OutsideMatrix=' . $outside_mks . ' (harus 2)',
                    'diagnostics' => [
                        'mata_kuliah_count' => $mk_count,
                        'total_sks' => $tot_sks,
                        'direct_cpl_mk_pair_count' => $dir_pair_count,
                        'mapped_course_count' => $mapped_mk_count,
                        'outside_matrix_count' => $outside_mks
                    ]
                ]);
                return;
            }
        }

        // Setelah rebuild, status diset NORMALIZED agar admin memverifikasi ulang
        $save_res = $this->_save_structured_curriculum_library($row->id, $payload, 'NORMALIZED');

        if (!$save_res['status']) {
            echo json_encode([
                'status' => false,
                'msg' => 'Bangun ulang gagal: ' . $save_res['msg'],
                'errors' => $validation['errors']
            ]);
            return;
        }

        echo json_encode([
            'status' => true,
            'msg' => 'Data terstruktur berhasil dibangun ulang dengan source_hash baru! Status diset NORMALIZED (silakan review & verifikasi).',
            'source_hash' => $save_res['source_hash'],
            'mata_kuliah_count' => $mk_count,
            'total_sks' => $tot_sks,
            'direct_cpl_mk_pair_count' => $dir_pair_count,
            'mapped_course_count' => $mapped_mk_count
        ]);
    }

    /**
     * AJAX: Ambil Ringkasan Hasil Normalisasi (Untuk Modal Lihat Hasil Normalisasi)
     */
    public function ajax_get_normalized_summary()
    {
        $this->output->set_content_type('application/json');
        $id = (int) $this->input->post('id', true);
        $row = $this->_get_pustaka_row_with_autoheal($id);

        if (!$row) {
            echo json_encode(['status' => false, 'msg' => 'Data kurikulum tidak ditemukan.']);
            return;
        }

        if (empty($row->normalized_json)) {
            echo json_encode([
                'status' => true,
                'has_normalized' => false,
                'id' => $row->id,
                'nama_prodi' => $row->nama_prodi,
                'judul_dokumen' => $row->judul_dokumen,
                'msg' => 'Dokumen belum pernah dinormalisasi.'
            ]);
            return;
        }

        $payload = json_decode($row->normalized_json, true);
        $validation = $this->_validate_structured_curriculum_library($payload);

        echo json_encode([
            'status' => true,
            'has_normalized' => true,
            'id' => $row->id,
            'nama_prodi' => $row->nama_prodi,
            'judul_dokumen' => $row->judul_dokumen,
            'tahun_kurikulum' => $row->tahun_kurikulum ?: '-',
            'normalization_status' => $row->normalization_status ?: 'NORMALIZED',
            'parser_version' => $row->parser_version ?: 'Phase-1.7',
            'schema_version' => $row->schema_version ?: '1.0',
            'source_hash' => $row->source_hash,
            'normalized_at' => $row->normalized_at ? date('d M Y, H:i', strtotime($row->normalized_at)) . ' WIB' : '-',
            'payload' => $payload,
            'validation' => $validation
        ]);
    }

    // =========================================================================
    // NORMALIZATION & SCHEMA V1.0 ENGINE HELPERS
    // =========================================================================

    protected function _calculate_source_hash($content)
    {
        return hash('sha256', (string) $content);
    }

    protected function _clean_curriculum_pdf_pollution($text)
    {
        $text = preg_replace('/POLITEKNIK\s*WBI\s*\d{4}/i', '', (string) $text);
        $text = preg_replace('/\d+\s*\|\s*P\s*a\s*g\s*e/i', '', $text);
        $text = preg_replace('/\d+\s*\|\s*Page/i', '', $text);
        $text = preg_replace('/Aspek\s+Kode\s+Diskripsi\s+Capaian\s+Pembelajaran\s+Lulusan/i', '', $text);
        return trim($text);
    }

    protected function _normalize_course_string_key($str)
    {
        return strtolower(preg_replace('/[^a-z0-9]/i', '', (string) $str));
    }

    protected function _validate_structured_curriculum_completeness($payload)
    {
        $errors = [];
        $cpl_count = isset($payload['official_cpl']) && is_array($payload['official_cpl']) ? count($payload['official_cpl']) : 0;
        $mk_count = isset($payload['mata_kuliah']) && is_array($payload['mata_kuliah']) ? count($payload['mata_kuliah']) : 0;

        if ($cpl_count === 0) {
            $errors[] = 'Completeness Error: official_cpl_count must be greater than 0.';
        }
        if ($mk_count === 0) {
            $errors[] = 'Completeness Error: mata_kuliah_count is 0 but curriculum document contains course distribution section.';
        }

        // Referential integrity check
        $all_mk = $payload['mata_kuliah'] ?? [];
        $direct_pairs = $payload['direct_cpl_mk_pairs'] ?? [];
        $bk_pairs = $payload['bk_mk_pairs'] ?? [];

        // Aggregate tracks lookup (e.g. INTERNSHIP_TRACK, TATA_NILAI)
        $aggregate_track_lookup = [];
        if (!empty($payload['matrix_reconciliation']['aggregate_tracks']) && is_array($payload['matrix_reconciliation']['aggregate_tracks'])) {
            foreach ($payload['matrix_reconciliation']['aggregate_tracks'] as $at) {
                if (!empty($at['aggregate_code'])) {
                    $aggregate_track_lookup[$this->_normalize_course_string_key($at['aggregate_code'])] = true;
                }
                if (!empty($at['matrix_column'])) {
                    $aggregate_track_lookup[$this->_normalize_course_string_key($at['matrix_column'])] = true;
                }
            }
        }
        $aggregate_track_lookup['internshiptrack'] = true;
        $aggregate_track_lookup['internship'] = true;
        $aggregate_track_lookup['tatanilai'] = true;

        if (!empty($direct_pairs) && $mk_count === 0) {
            $errors[] = 'Referential Integrity Error: direct_cpl_mk_pairs exist but mata_kuliah_count is 0.';
        }

        foreach ($direct_pairs as $dp) {
            $p_code = $this->_normalize_course_string_key($dp['mk_code'] ?? '');
            $p_name = $this->_normalize_course_string_key($dp['mk_name'] ?? '');
            $is_aggregate = (!empty($dp['mapping_scope']) && $dp['mapping_scope'] === 'TRACK_AGGREGATE')
                || isset($aggregate_track_lookup[$p_code])
                || isset($aggregate_track_lookup[$p_name]);
            
            if ($is_aggregate) {
                continue;
            }

            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($p_code) && $p_code === $m_code) || (!empty($p_name) && (str_contains($m_name, $p_name) || str_contains($p_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: direct_cpl_mk_pair pointing to unresolvable MK [{$dp['mk_code']}] {$dp['mk_name']}.";
            }
        }

        foreach ($bk_pairs as $bp) {
            $b_code = $this->_normalize_course_string_key($bp['mk_code'] ?? '');
            $b_name = $this->_normalize_course_string_key($bp['mk_name'] ?? '');
            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($b_code) && $b_code === $m_code) || (!empty($b_name) && (str_contains($m_name, $b_name) || str_contains($b_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: bk_mk_pair pointing to unresolvable MK [{$bp['mk_code']}] {$bp['mk_name']}.";
            }
        }

        // Effective CPL-MK pairs validation
        $effective_pairs = $payload['effective_cpl_mk_pairs'] ?? [];
        $cpls = $payload['official_cpl'] ?? [];
        $cpl_lookup = [];
        foreach ($cpls as $c) {
            $code = $c['code'] ?? '';
            if (empty($code)) continue;
            $cpl_lookup[$code] = true;
            $unhyphenated = str_replace('-', '', $code);
            $cpl_lookup[$unhyphenated] = true;
            if (str_starts_with($code, 'KU-')) {
                $cpl_lookup[str_replace('KU-', 'U-', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'U', $code)] = true;
            } elseif (str_starts_with($code, 'U-')) {
                $cpl_lookup[str_replace('U-', 'KU-', $code)] = true;
                $cpl_lookup[str_replace('U-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('U-', 'U', $code)] = true;
            }
            if (str_starts_with($code, 'KK-')) {
                $cpl_lookup[str_replace('KK-', 'KS-', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KS', $code)] = true;
            } elseif (str_starts_with($code, 'KS-')) {
                $cpl_lookup[str_replace('KS-', 'KK-', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KS', $code)] = true;
            }
        }
        $bk_lookup = [];
        foreach (($payload['bahan_kajian'] ?? []) as $b) {
            $bk_lookup[$b['code']] = true;
        }

        foreach ($effective_pairs as $ep) {
            $ep_cpl = $ep['cpl_code'] ?? '';
            $ep_mk_code = $this->_normalize_course_string_key($ep['mk_code'] ?? '');
            $ep_mk_name = $this->_normalize_course_string_key($ep['mk_name'] ?? '');
            $ep_mtype = $ep['mapping_type'] ?? '';
            $ep_bk = $ep['bk_code'] ?? '';

            if (!isset($cpl_lookup[$ep_cpl])) {
                $errors[] = "Referential Integrity Error: effective_cpl_mk_pair uses invalid cpl_code '{$ep_cpl}'.";
            }
            if ($ep_mtype === 'DERIVED_VIA_BK' && !isset($bk_lookup[$ep_bk])) {
                $errors[] = "Referential Integrity Error: derived effective pair uses unresolvable bk_code '{$ep_bk}'.";
            }

            $is_aggregate = (!empty($ep['mapping_scope']) && $ep['mapping_scope'] === 'TRACK_AGGREGATE')
                || isset($aggregate_track_lookup[$ep_mk_code])
                || isset($aggregate_track_lookup[$ep_mk_name]);
            if ($is_aggregate) {
                continue;
            }

            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($ep_mk_code) && $ep_mk_code === $m_code) || (!empty($ep_mk_name) && (str_contains($m_name, $ep_mk_name) || str_contains($ep_mk_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: effective_cpl_mk_pair pointing to unresolvable MK [{$ep['mk_code']}] {$ep['mk_name']}.";
            }
        }

        // Aggregate Domain Mappings validation (e.g. TATA_NILAI)
        $agg_mappings = $payload['aggregate_domain_mappings'] ?? [];
        foreach ($agg_mappings as $am) {
            $a_code = $this->_normalize_course_string_key($am['mk_code'] ?? '');
            $a_name = $this->_normalize_course_string_key($am['mk_name'] ?? '');
            $is_aggregate = (!empty($am['mapping_scope']) && $am['mapping_scope'] === 'TRACK_AGGREGATE')
                || isset($aggregate_track_lookup[$a_code])
                || isset($aggregate_track_lookup[$a_name]);
            if ($is_aggregate) {
                continue;
            }

            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($a_code) && $a_code === $m_code) || (!empty($a_name) && (str_contains($m_name, $a_name) || str_contains($a_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: aggregate_domain_mapping pointing to unresolvable MK [{$am['mk_code']}] {$am['mk_name']}.";
            }
        }

        return [
            'valid' => empty($errors),
            'errors' => $errors
        ];
    }

    protected function _validate_structured_curriculum_library($payload)
    {
        $errors = [];
        if (!is_array($payload)) {
            return ['valid' => false, 'errors' => ['Payload bukan array/objek JSON valid.']];
        }

        if (empty($payload['schema_version'])) {
            $errors[] = 'Missing schema_version.';
        }

        if (empty($payload['prodi']['nama_resmi'])) {
            $errors[] = 'Missing prodi.nama_resmi.';
        }

        if (!isset($payload['official_cpl']) || !is_array($payload['official_cpl']) || empty($payload['official_cpl'])) {
            $errors[] = 'official_cpl harus berupa array non-empty.';
        } else {
            $seen_codes = [];
            foreach ($payload['official_cpl'] as $idx => $cpl) {
                $code = $cpl['code'] ?? '';
                if (empty($code)) {
                    $errors[] = "official_cpl[{$idx}] tidak memiliki kode.";
                } elseif (isset($seen_codes[$code])) {
                    $errors[] = "Duplikasi kode CPL resmi: {$code}.";
                }
                $seen_codes[$code] = true;

                if (empty($cpl['category']) || !in_array($cpl['category'], ['S', 'P', 'KU', 'KK', 'U', 'K', 'SIKAP', 'PENGETAHUAN', 'KETERAMPILAN KHUSUS', 'KETERAMPILAN UMUM', 'CPL', 'OTHER'])) {
                    $errors[] = "CPL {$code} memiliki kategori tidak valid: " . ($cpl['category'] ?? 'kosong');
                }
                if (empty($cpl['description'])) {
                    $errors[] = "CPL {$code} memiliki deskripsi kosong.";
                }
            }
        }

        if (isset($payload['cpl_bk_mapping'])) {
            $status = $payload['cpl_bk_mapping']['status'] ?? '';
            if (!in_array($status, ['PARSED', 'AVAILABLE_UNPARSED', 'NOT_AVAILABLE'])) {
                $errors[] = "Status cpl_bk_mapping tidak valid: {$status}.";
            }
            if ($status === 'PARSED' && (!is_array($payload['cpl_bk_mapping']['pairs'] ?? null) || ($payload['cpl_bk_mapping']['mappable_count'] ?? null) === null)) {
                $errors[] = "Status PARSED mewajibkan mappable_count integer dan array pairs.";
            }
        }

        if (isset($payload['cpl_mk_mapping_audit'])) {
            $audit = $payload['cpl_mk_mapping_audit'];
            $m_status = $audit['mapping_parse_status'] ?? '';
            if (!in_array($m_status, ['SOURCE_MAPPING_PARSED', 'SOURCE_MAPPING_PARTIAL', 'SOURCE_MAPPING_AVAILABLE_UNPARSED', 'SOURCE_MAPPING_PARSER_ERROR', 'SOURCE_MAPPING_NOT_AVAILABLE'])) {
                $errors[] = "Status mapping_parse_status pada cpl_mk_mapping_audit tidak valid: {$m_status}.";
            }
        }

        // Run completeness and referential integrity rules
        $completeness = $this->_validate_structured_curriculum_completeness($payload);
        if (!$completeness['valid']) {
            $errors = array_merge($errors, $completeness['errors']);
        }

        $bk_completeness = $this->_validate_bahan_kajian_completeness($payload);
        if (!$bk_completeness['valid']) {
            $errors = array_merge($errors, $bk_completeness['errors']);
        }

        return [
            'valid' => empty($errors),
            'errors' => $errors
        ];
    }

    protected function _validate_bahan_kajian_completeness($payload)
    {
        $errors = [];
        $bks = $payload['bahan_kajian'] ?? [];
        $prodi = $payload['prodi']['nama_resmi'] ?? '';

        if (empty($bks) || !is_array($bks)) {
            $errors[] = 'Completeness Error: bahan_kajian array cannot be empty.';
            return ['valid' => false, 'errors' => $errors];
        }

        $seen = [];
        foreach ($bks as $idx => $b) {
            $code = $b['code'] ?? '';
            $name = $b['name'] ?? '';
            $source_name = $b['source_name'] ?? '';

            if (empty($code)) {
                $errors[] = "Bahan Kajian pada indeks {$idx} tidak memiliki kode.";
            } elseif (isset($seen[$code])) {
                $errors[] = "Duplikasi kode Bahan Kajian: {$code}.";
            }
            $seen[$code] = true;

            if (empty($name)) {
                $errors[] = "Bahan Kajian {$code} memiliki nama kosong.";
            }
            if (empty($source_name)) {
                if (!empty($name)) {
                    $b['source_name'] = $name;
                } else {
                    $errors[] = "Bahan Kajian {$code} memiliki source_name kosong (Source Fidelity Error).";
                }
            }

            // Pollution check
            if (preg_match('/^(?:Landasan|Visi|Misi|Tujuan\s*Program|Bab\b|Matriks\b|Struktur\s*Mata|Distribusi\s*Mata)/i', $name)) {
                $errors[] = "Pollution terdeteksi pada Bahan Kajian {$code}: '{$name}'.";
            }
        }

        // Expected count validation per prodi
        $count = count($bks);
        if (stripos($prodi, 'Agribisnis') !== false && $count !== 20) {
            $errors[] = "Agribisnis Hortikultura harus memiliki tepat 20 Bahan Kajian (ditemukan {$count}).";
        } elseif (stripos($prodi, 'Perangkat Lunak') !== false && $count !== 11) {
            $errors[] = "Teknologi Rekayasa Perangkat Lunak harus memiliki tepat 11 Bahan Kajian (ditemukan {$count}).";
        } elseif (stripos($prodi, 'Akuntansi') !== false && $count !== 13) {
            $errors[] = "Akuntansi Perpajakan harus memiliki tepat 13 Bahan Kajian (ditemukan {$count}).";
        } elseif (stripos($prodi, 'Konvensi') !== false && $count !== 32) {
            $errors[] = "Pengelolaan Konvensi dan Acara harus memiliki tepat 32 Bahan Kajian (ditemukan {$count}).";
        } elseif ((stripos($prodi, 'Pemasaran') !== false || stripos($prodi, 'Perusahaan') !== false) && $count !== 10) {
            $errors[] = "Manajemen Pemasaran Internasional harus memiliki tepat 10 Bahan Kajian (ditemukan {$count}).";
        }

        // Referential integrity check for BK-MK pairs
        $all_mk = $payload['mata_kuliah'] ?? [];
        $bk_mk_pairs = $payload['bk_mk_pairs'] ?? [];
        foreach ($bk_mk_pairs as $pair) {
            $bkc = $pair['bk_code'] ?? '';
            if (!isset($seen[$bkc])) {
                $errors[] = "Referential Integrity Error: bk_mk_pair menggunakan bk_code tidak valid '{$bkc}'.";
            }
        }

        // Referential integrity check for CPL-BK pairs
        $cpl_bk_pairs = $payload['cpl_bk_mapping']['pairs'] ?? [];
        $cpls = $payload['official_cpl'] ?? [];
        $cpl_lookup = [];
        foreach ($cpls as $c) {
            $code = $c['code'] ?? '';
            if (empty($code)) continue;
            $cpl_lookup[$code] = true;
            $unhyphenated = str_replace('-', '', $code);
            $cpl_lookup[$unhyphenated] = true;
            if (str_starts_with($code, 'KU-')) {
                $cpl_lookup[str_replace('KU-', 'U-', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'U', $code)] = true;
            } elseif (str_starts_with($code, 'U-')) {
                $cpl_lookup[str_replace('U-', 'KU-', $code)] = true;
                $cpl_lookup[str_replace('U-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('U-', 'U', $code)] = true;
            }
            if (str_starts_with($code, 'KK-')) {
                $cpl_lookup[str_replace('KK-', 'KS-', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KS', $code)] = true;
            } elseif (str_starts_with($code, 'KS-')) {
                $cpl_lookup[str_replace('KS-', 'KK-', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KS', $code)] = true;
            }
        }

        foreach ($cpl_bk_pairs as $pair) {
            $bkc = $pair['bk_code'] ?? '';
            $cpc = $pair['cpl_code'] ?? '';
            if (!isset($seen[$bkc])) {
                $errors[] = "Referential Integrity Error: cpl_bk_pair menggunakan bk_code tidak valid '{$bkc}'.";
            }
            if (!isset($cpl_lookup[$cpc])) {
                $errors[] = "Referential Integrity Error: cpl_bk_pair menggunakan cpl_code tidak valid '{$cpc}'.";
            }
        }

        return [
            'valid' => empty($errors),
            'errors' => $errors
        ];
    }

