    /**
     * AJAX: Get Maintenance Status (Exclusive for gege.satya@wbi.ac.id)
     */
    public function ajax_get_maintenance_status()
    {
        $this->output->set_content_type('application/json');
        if (!$this->Maintenance_model->is_user_exempt()) {
            echo json_encode(['status' => 'error', 'msg' => 'Akses ditolak. Fitur ini khusus administrator sistem (gege.satya@wbi.ac.id).']);
            return;
        }

        $statuses = $this->Maintenance_model->get_all_statuses();
        echo json_encode([
            'status' => 'success',
            'data' => $statuses
        ]);
    }

    /**
     * AJAX: Toggle Maintenance Status (Exclusive for gege.satya@wbi.ac.id)
     */
    public function ajax_toggle_maintenance()
    {
        $this->output->set_content_type('application/json');
        if (!$this->Maintenance_model->is_user_exempt()) {
            echo json_encode(['status' => 'error', 'msg' => 'Akses ditolak. Fitur ini khusus administrator sistem (gege.satya@wbi.ac.id).']);
            return;
        }

        $module_key = trim($this->input->post('module_key'));
        $is_active  = (int)$this->input->post('is_active');
        $message    = $this->input->post('message');

        if (!in_array($module_key, ['kurikulum', 'studio_rps', 'all'])) {
            echo json_encode(['status' => 'error', 'msg' => 'Modul tidak valid.']);
            return;
        }

        $user_obj = $this->ion_auth->user()->row();
        $updated_by = $user_obj->email ?? ($user_obj->username ?? 'gege.satya@wbi.ac.id');

        if ($module_key === 'all') {
            $this->Maintenance_model->set_maintenance('kurikulum', $is_active, $message, $updated_by);
            $this->Maintenance_model->set_maintenance('studio_rps', $is_active, $message, $updated_by);
        } else {
            $this->Maintenance_model->set_maintenance($module_key, $is_active, $message, $updated_by);
        }

        $statuses = $this->Maintenance_model->get_all_statuses();
        $label_mod = ($module_key === 'all') ? 'Semua Modul (Kurikulum & Studio RPS)' : (($module_key === 'kurikulum') ? 'Modul Kurikulum' : 'Studio RPS OBE');

        echo json_encode([
            'status' => 'success',
            'msg' => 'Status pemeliharaan ' . $label_mod . ' berhasil di' . ($is_active ? 'aktifkan (Terkunci)' : 'nonaktifkan (Terbuka)') . '.',
            'data' => $statuses
        ]);
    }
}

